// Dias Panel raporu (/rapor), oluşturulmuş sayfa: görseller gömülü. Elle düzenlemeyin.
export default "<!doctype html><html lang=\"tr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex, nofollow\"><title>Dias Panel Haftalık Rapor</title>\n<style>*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0}\n/* Dias Panel is always dark: one committed look, pages stacked like the app screens. */\n:root{--bg:#061021;--ink:#eaf1fb;--mute:#8aa0bd;--line:#1c3558;color-scheme:dark}\nbody{background:var(--bg);color:var(--ink);font-family:Roboto,'Segoe UI',system-ui,sans-serif;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:20px 32px}\nmain{max-width:720px;margin:0 auto;display:grid;gap:18px}\np{color:var(--mute);font-size:13px;text-align:center;margin:0}\nfigure{margin:0;border:1px solid var(--line);border-radius:14px;overflow:hidden}\nimg{display:block;width:100%;height:auto;max-width:100%}\n.asya{border:1px solid #2a5b9a;border-radius:14px;background:linear-gradient(180deg,#10274a,#0a1830);box-shadow:0 0 22px rgba(57,135,229,.18);padding:14px;display:grid;gap:10px}\n.ah{display:flex;align-items:center;gap:10px}.ah img{width:40px;height:40px;filter:drop-shadow(0 0 6px rgba(201,168,76,.4))}\n.ah b{display:block;font-size:16px}.ah small{color:var(--mute);font-size:12.5px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chips button,#send{font:inherit;font-size:13px;text-align:left;color:var(--ink);background:#123056;border:1px solid #2a5b9a;border-radius:999px;padding:6px 12px;cursor:pointer}\n.chips button:hover,#send:hover{background:#18406f}\nbutton:focus-visible,input:focus-visible{outline:2px solid #6fb0ff;outline-offset:2px}\n.more summary{cursor:pointer;font-size:13px;color:#8fc1ff;list-style:none;display:inline-flex;align-items:center;gap:6px;padding:4px 2px}\n.more summary::-webkit-details-marker{display:none}\n.more summary::after{content:\"▾\";transition:transform .2s}\n.more[open] summary::after{transform:rotate(180deg)}\n.more .chips{margin-top:8px;padding-top:10px;border-top:1px solid var(--line)}\n.log{display:grid;gap:8px}.log:empty{display:none}\n.m-u,.m-a{font-size:14px;line-height:1.5;padding:9px 12px;border-radius:12px;max-width:92%;white-space:pre-wrap;overflow-wrap:anywhere}\n.m-u{justify-self:end;background:#1d5fd1}.m-a{justify-self:start;background:#0e2344;border:1px solid var(--line)}\nform{display:flex;gap:8px}form input{flex:1;min-width:0;font:inherit;font-size:14px;color:var(--ink);background:#061021;border:1px solid var(--line);border-radius:10px;padding:9px 12px}\n#send{border-radius:10px;padding:9px 16px;background:#1d5fd1;border-color:#1d5fd1}\n#send:disabled{opacity:.5;cursor:default}\n.off{font-size:13px;color:var(--mute);text-align:left}\n\nbody{position:relative;isolation:isolate;min-height:100vh}\nbody::before{content:\"\";position:fixed;inset:0;z-index:-2;pointer-events:none;background:\n radial-gradient(80% 50% at 50% 30%,rgba(10,30,66,.25),rgba(5,14,30,.80) 100%),\n linear-gradient(180deg,rgba(12,34,74,.62),rgba(6,16,33,.88)),\n url(\"data:image/svg+xml;base64,\") center 30%/cover no-repeat,#061021}\nbody::after{content:\"\";position:fixed;inset:-10% -30% 0;z-index:-1;pointer-events:none;mix-blend-mode:screen;background:\n radial-gradient(55% 22% at 85% 0%,rgba(140,190,255,.18),transparent 70%),\n linear-gradient(115deg,transparent 30%,rgba(120,175,255,.10) 36%,transparent 42%),\n linear-gradient(115deg,transparent 47%,rgba(160,205,255,.08) 51%,transparent 56%),\n linear-gradient(115deg,transparent 62%,rgba(120,175,255,.06) 65%,transparent 69%);animation:sweep 14s ease-in-out infinite alternate}\n@keyframes sweep{from{transform:translateX(-4%)}to{transform:translateX(4%)}}\n@media (prefers-reduced-motion:reduce){body::after{animation:none}}\n.asya{background:linear-gradient(180deg,rgba(16,39,74,.78),rgba(10,24,48,.86));backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);box-shadow:0 0 28px rgba(57,135,229,.25),inset 0 1px 0 rgba(190,220,255,.15)}\nfigure{box-shadow:0 10px 30px rgba(0,0,0,.35)}\n.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}\n</style>\n<main><section class=\"asya\" id=\"asya\" aria-label=\"Asya AI\">\n  <div class=\"ah\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"40\" height=\"40\"><div><b>Asya AI</b><small>Bu raporla ilgili sorunu sor</small></div></div>\n  <div class=\"chips\" id=\"chips\">\n    <button type=\"button\">Google gösterim ve tıklamaları son haftada ne kadar arttı?</button>\n    <button type=\"button\">%1,4 tıklama oranı ve 10,5 ortalama sıra ne anlama geliyor?</button>\n    <button type=\"button\">Hangi aramalarda görünüp tıklanmıyoruz, nasıl düzeltilir?</button>\n  </div>\n  <details class=\"more\"><summary>Diğer Google soruları (6)</summary>\n  <div class=\"chips\">\n    <button type=\"button\">Google'dan en çok tıklanan sayfalar hangileri?</button>\n    <button type=\"button\">Hangi sayfalar yükseliyor, hangileri düşüyor?</button>\n    <button type=\"button\">Aylık ve yıllık Google projeksiyonu nasıl hesaplandı?</button>\n    <button type=\"button\">Google trafiği hangi ülkelerden ve cihazlardan geliyor?</button>\n    <button type=\"button\">Son 24 saatte Google performansı nasıl?</button>\n    <button type=\"button\">Site haritası ve indeks durumu sağlıklı mı?</button>\n  </div></details>\n  <div class=\"log\" id=\"log\" aria-live=\"polite\"></div>\n  <form id=\"askf\"><label for=\"q\" class=\"sr\">Soru</label><input id=\"q\" autocomplete=\"off\" placeholder=\"Örn: En çok hangi sayfa okunuyor?\" maxlength=\"300\"><button id=\"send\" type=\"submit\">Sor</button></form>\n  <p class=\"off\" id=\"off\" hidden>Asya bu görünümde çalışamıyor. Raporun tamamı aşağıda.</p>\n</section>\n<p>complaintca.ca · 6 Temmuz – 24 Ekim 2026 · 4 sayfa</p><figure><img src=\"data:image/webp;base64,\" alt=\"Dias Panel · Büyüme özeti\" width=\"1440\" height=\"2560\"></figure><figure><img src=\"data:image/webp;base64,\" alt=\"Dias Panel · Haftalık performans özeti\" width=\"1440\" height=\"2560\"></figure><figure><img src=\"data:image/webp;base64,\" alt=\"Dias Panel · Trafik ve ziyaretçi analizi\" width=\"1440\" height=\"2560\"></figure><figure><img src=\"data:image/webp;base64,\" alt=\"Dias Panel · Google trafik ve performans\" width=\"1440\" height=\"2560\"></figure></main><script>\n(function(){\nvar DATA=`complaintca.ca raporu (Dias Panel). Dönem: 6 Temmuz – 24 Ekim 2026 (yaklaşık 3,5 ay, 16 hafta).\nSite: ComplaintCA bir hukuk platformu. Kanada'da işletme, ev sahibi, okul veya kamu kurumlarıyla yaşanan sorunları ilgili kanun ve eyalet mevzuatına göre ele alır, doğru kuruma doğru prosedürle yönlendirir. Ücretsiz ve anonim; başvuru takibi, avukat bulma, dolandırıcılık kontrolü. İspanya için İspanyolca sürüm var. Fikir ve tasarım kurucuya ait; Dias Panel yol haritası olarak kullanıldı, yazılımda Claude yapay zekâ asistanından yararlanıldı.\nBÜYÜME: İlk gün 0 gösterim. Güncel hız ayda ~34.400 gösterim ve ~470 tık (son haftanın değerleri × 30/7). Yayından bu yana aylık ortalama ~7.100 gösterim, ~81 tık; güncel hız gösterimde 4,9 kat, tıkta 5,8 kat. İlk haftalara göre yaklaşık 25 kat (grafikten okunan yaklaşık değer). Bir haftada 2 kat artış (tık ~59 → 109, gösterim ~3.970 → 8.025, %85 ve %102 artış). Toplam tıkın %36'sı son 7 günde. Kümülatif: 26.202 gösterim, 299 Google tıkı. Yıllık projeksiyon mevcut hızla ~5.600 tık, ~410.000 gösterim. Büyüme sürerse 30 gün içinde 500+ tık beklenir. Aylık 1.250 tekil kullanıcı (tüm kaynaklar, Vercel Analytics).\nKİTLE (18–24 Ekim): 596 ziyaretçi (günlük ort. 85; Sal 91, Çar 123, Per 87, Cum 72, Cmt 63, Paz 106, Pzt 54). Google tıkının %94'ü Kanada'dan (102/109; DE, ES, MX, CHN, PAN birer). Cihaz: telefon %50, bilgisayar %50 (Google gösteriminde telefon %46, bilgisayar %53, tablet %1). Ortalama kalma süresi 1 dk 18 sn – 1 dk 34 sn. Şehirler: Toronto 92; Santa Clara 58, Ashburn 46, Atlanta 26, Singapore 21, Council Bluffs 20 (ABD şehirleri büyük ölçüde veri merkezi/bot trafiği). Yoğun saatler (Toronto): Çar 10–13, Paz 10–12, Sal 16–18.\nEN ÇOK OKUNAN: Ana sayfa 280; gio-general-insurance-ombudservice-canada 37; school-principal-complaint-ontario 29; contractor-renovation-complaint-ontario 26; how-to-file-small-claims-ontario 19; mail-theft-stolen-cheque-canada 19.\nGOOGLE (18–24 Ekim): 109 tık (+%85), 8.025 gösterim (+%102), tıklama oranı %1,4, ortalama sıra 10,5. Son 24 saat: 1.281 gösterim, 20 tık. En çok tıklanan: school-principal-complaint-ontario 19, report-a-teacher-canada 9, contractor-renovation-complaint-ontario 8, how-to-file-small-claims-ontario 7, complaint-against-landlord-ontario-ltb-t2-t6 6, fake-cra-letter-text-call-verify-report 6. Yükselen: school-principal +11, report-a-teacher +6, landlord-ltb +6. Düşen: ontario-energy-bill-dispute -4, insurance-claim-denied -1, report-fraud-to-your-bank -1. Fırsatlar (görünüyor ama tık yok): \"general insurance ombudservice\" 63 gösterim sıra 6.1; \"my car insurance cancelled\" 23 gösterim sıra 10.1; \"1 800 983 8472\" 22 gösterim sıra 9.6. Site haritası sağlıklı, 99 adres. Önerilen adımlar: fırsat sayfalarının başlık ve ilk paragrafını güçlendirmek; okul/öğretmen konulu yeni içerik; enerji faturası yazısını kış dönemine göre güncellemek.`;\nvar RULES='Sen Asya\\'sın, ComplaintCA\\'nın yapay zekâ asistanı. Aşağıdaki rapor verisine dayanarak soruyu kısa, net ve profesyonel cevapla (en fazla 4-5 cümle). Soru hangi dildeyse o dilde cevap ver. Sadece bu verideki rakamları kullan; veride olmayan bir şey sorulursa bunun raporda olmadığını söyle, tahmin uydurma. Platformun teknik altyapısı, yazılımı veya iç işleyişi sorulursa ayrıntı verme; bunun gizli olduğunu nazikçe söyle ve kurucuyla iletişime yönlendir. Markdown kullanma, düz metin yaz.\\n\\nRAPOR VERİSİ:\\n'+DATA;\nvar log=document.getElementById('log'),f=document.getElementById('askf'),q=document.getElementById('q'),send=document.getElementById('send'),box=document.getElementById('asya');\nvar hist=[],busy=false;\nfunction off(){box.querySelectorAll('.chips,.more,form,.log').forEach(function(e){e.hidden=true});document.getElementById('off').hidden=false}\nfunction bubble(cls,t){var d=document.createElement('div');d.className=cls;d.textContent=t;log.appendChild(d);return d}\nasync function ask(text){\n  text=text.trim(); if(!text||busy) return;\n  busy=true;send.disabled=true;q.value='';\n  bubble('m-u',text); var a=bubble('m-a','Asya düşünüyor…');\n  var turns=hist.slice(-6).concat([{role:'user',content:text}]);\n  try{\n    var r=await fetch('/api/claude-proxy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({max_tokens:600,system:RULES,messages:turns})});\n    if(r.status===429){a.textContent='Biraz yoğunum, bir dakika sonra tekrar dener misin?'}\n    else{var d=await r.json();var t=r.ok&&d.content?d.content.map(function(c){return c.text||''}).join('').trim():'';\n      if(t){a.textContent=t;hist.push({role:'user',content:text},{role:'assistant',content:t})}else a.textContent='Şu an cevap veremedim, lütfen tekrar dene.'}\n  }catch(e){a.textContent='Bağlantı sorunu, lütfen tekrar dene.'}\n  busy=false;send.disabled=false;\n}\nf.addEventListener('submit',function(e){e.preventDefault();ask(q.value)});\nbox.addEventListener('click',function(e){var b=e.target.closest('.chips button');if(b){ask(b.textContent);var d=b.closest('details');if(d)d.open=false}});\n})();\n</script>\n</body></html>";
